# Terraform: task definition do ECS (Fargate)
resource "aws_ecs_task_definition" "app" {
  family                   = "spring-app"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 512
  memory                   = 1024
  container_definitions = jsonencode([{
    name      = "app"
    image     = "minha-app:1.4.0"   # versão fixa, nunca latest
    essential = true
  }])
}
